def merge(iv):
    out = []
    for s, e in sorted(iv):
        if out and s <= out[-1][1]:
            out[-1][1] = max(out[-1][1], e)
        else:
            out.append([s, e])
    return out

import time
class Bucket:
    def __init__(self, rate, cap):
        self.rate, self.cap, self.tokens, self.t = rate, cap, cap, time.monotonic()
    def allow(self):
        now = time.monotonic()
        self.tokens = min(self.cap, self.tokens + (now - self.t) * self.rate)
        self.t = now
        if self.tokens >= 1:
            self.tokens -= 1; return True
        return False

import bisect, hashlib
h = lambda s: int(hashlib.md5(s.encode()).hexdigest(), 16)
class Ring:
    def __init__(self, nodes, v=100):
        self.ring = sorted((h(f'{n}#{i}'), n) for n in nodes for i in range(v))
        self.keys = [k for k, _ in self.ring]
    def get(self, key):
        i = bisect.bisect(self.keys, h(key)) % len(self.ring)
        return self.ring[i][1]
